"""Phase 4.4 — statistiques BÉCHÉFAA enrichies.

Lecture seule. Aucun Z, aucune clôture, aucune écriture métier.
"""
from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
from flask import jsonify, Response, request

PARIS=ZoneInfo('Europe/Paris'); UTC=ZoneInfo('UTC')

def _bounds():
    today=datetime.now(PARIS).date(); period=request.args.get('period','today')
    if period=='week': start=today-timedelta(days=today.weekday()); end=today+timedelta(days=1)
    elif period=='month': start=today.replace(day=1); end=today+timedelta(days=1)
    elif period=='custom':
        try:
            start=datetime.strptime(request.args.get('start',''),'%Y-%m-%d').date(); end=datetime.strptime(request.args.get('end',''),'%Y-%m-%d').date()+timedelta(days=1)
        except ValueError: raise ValueError('Période personnalisée invalide')
        if end<=start: raise ValueError('La date de fin doit être égale ou postérieure à la date de début')
    else: period='today'; start=today; end=today+timedelta(days=1)
    a=datetime.combine(start,time.min,PARIS); b=datetime.combine(end,time.min,PARIS)
    return int(a.astimezone(UTC).timestamp()*1000),int(b.astimezone(UTC).timestamp()*1000),period,start.isoformat(),(end-timedelta(days=1)).isoformat()

def register_statistics_phase44(app,db):
 @app.get('/api/statistics/today-phase44')
 def statistics_today_phase44():
  try: start_ms,end_ms,period,start_date,end_date=_bounds()
  except ValueError as e: return jsonify({'ok':False,'error':str(e)}),400
  try:
   with db() as conn:
    orders=conn.execute("SELECT COUNT(*) FILTER (WHERE COALESCE(cancellation_hidden,FALSE)=FALSE) orders_count,COALESCE(SUM(total) FILTER (WHERE COALESCE(cancellation_hidden,FALSE)=FALSE),0) orders_total,COALESCE(AVG(total) FILTER (WHERE COALESCE(cancellation_hidden,FALSE)=FALSE),0) average_ticket FROM caisse_orders WHERE created_at >= %s AND created_at < %s",(start_ms,end_ms)).fetchone()
    modes=conn.execute("SELECT COALESCE(NULLIF(UPPER(source),''),'CAISSE') source,COUNT(*) count,COALESCE(SUM(total),0) total FROM caisse_orders WHERE created_at >= %s AND created_at < %s AND COALESCE(cancellation_hidden,FALSE)=FALSE GROUP BY 1 ORDER BY total DESC",(start_ms,end_ms)).fetchall()
    tx=conn.execute("SELECT COALESCE(SUM(CASE WHEN transaction_type='PAYMENT' AND status='SUCCEEDED' THEN amount ELSE 0 END),0) payments,COALESCE(SUM(CASE WHEN transaction_type='REFUND' AND status='SUCCEEDED' THEN amount ELSE 0 END),0) refunds FROM caisse_payment_transactions WHERE created_at >= %s AND created_at < %s",(start_ms,end_ms)).fetchone()
    methods=conn.execute("SELECT UPPER(COALESCE(NULLIF(method,''),'AUTRE')) method,COALESCE(SUM(CASE WHEN transaction_type='PAYMENT' AND status='SUCCEEDED' THEN amount WHEN transaction_type='REFUND' AND status='SUCCEEDED' THEN -amount ELSE 0 END),0) net FROM caisse_payment_transactions WHERE created_at >= %s AND created_at < %s GROUP BY 1 ORDER BY net DESC",(start_ms,end_ms)).fetchall()
    daily=conn.execute("SELECT TO_CHAR((TO_TIMESTAMP(created_at::double precision/1000.0) AT TIME ZONE 'Europe/Paris')::date,'YYYY-MM-DD') day,COUNT(*) count,COALESCE(SUM(total),0) total FROM caisse_orders WHERE created_at >= %s AND created_at < %s AND COALESCE(cancellation_hidden,FALSE)=FALSE GROUP BY 1 ORDER BY 1",(start_ms,end_ms)).fetchall()
    products=conn.execute("SELECT COALESCE(NULLIF(i.name,''),'Produit') name,SUM(i.qty) qty,COALESCE(SUM(i.qty*i.unit_price),0) revenue FROM caisse_order_items i JOIN caisse_orders o ON o.id=i.order_id WHERE o.created_at >= %s AND o.created_at < %s AND COALESCE(o.cancellation_hidden,FALSE)=FALSE GROUP BY COALESCE(NULLIF(i.name,''),'Produit')",(start_ms,end_ms)).fetchall()
   paid=float(tx['payments'] or 0); refunded=float(tx['refunds'] or 0)
   ranked=sorted([{'name':r['name'],'qty':int(r['qty'] or 0),'revenue':float(r['revenue'] or 0)} for r in products],key=lambda x:(-x['qty'],-x['revenue'],x['name']))
   least=sorted(ranked,key=lambda x:(x['qty'],x['revenue'],x['name']))[:10]
   return jsonify({'ok':True,'period':period,'start_date':start_date,'end_date':end_date,'orders':{'count':int(orders['orders_count'] or 0),'gross_total':float(orders['orders_total'] or 0),'average_ticket':float(orders['average_ticket'] or 0)},'cashflow':{'payments':paid,'refunds':refunded,'net':paid-refunded},'sources':[{'source':r['source'],'count':int(r['count']),'total':float(r['total'] or 0)} for r in modes],'methods':[{'method':r['method'],'net':float(r['net'] or 0)} for r in methods],'daily':[{'day':r['day'],'count':int(r['count']),'total':float(r['total'] or 0)} for r in daily],'top_products':ranked[:10],'least_products':least})
  except Exception as exc: return jsonify({'ok':False,'error':'Statistiques indisponibles','detail':str(exc)}),500

 @app.get('/statistiques')
 def statistics_page_phase44():
  return Response(r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BÉCHÉFAA • Statistiques</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f5f7;font-family:Arial;color:#111827}.w{max-width:1180px;margin:28px auto;padding:18px}.muted{color:#667085}.filters,.cards{display:grid;gap:12px;margin:18px 0}.filters{grid-template-columns:2fr 1fr 1fr auto}.cards{grid-template-columns:repeat(5,1fr)}.card,.box{background:#fff;border-radius:15px;padding:18px;box-shadow:0 4px 18px #0001}.v{font-size:25px;font-weight:900;margin-top:8px}.lab{font-size:12px;font-weight:800;color:#667085;text-transform:uppercase}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #eee}.row:last-child{border:0}select,input,button{min-height:44px;border:1px solid #d0d5dd;border-radius:9px;padding:8px;font-size:14px}button{background:#111827;color:white;font-weight:800;cursor:pointer}.datewrap{position:relative}.datewrap input{width:100%;padding-right:42px}.cal{position:absolute;right:4px;top:4px;width:36px;min-height:36px;border:0;background:#eef2f6;color:#111827}.charts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.chartbox{height:300px}.chartbox canvas{width:100%;height:235px}.legend{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;margin-top:8px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}.full{grid-column:1/-1}.warn{background:#fff8e6;border:1px solid #f5d38b;padding:10px;border-radius:10px;font-size:12px;margin-top:14px}@media(max-width:850px){.filters,.cards,.grid,.charts{grid-template-columns:1fr 1fr}.full{grid-column:1/-1}}@media(max-width:600px){.filters,.cards,.grid,.charts{grid-template-columns:1fr}}</style></head><body><div class="w"><h1>Statistiques / Rapports</h1><div class="filters"><select id="period"><option value="today">Aujourd'hui</option><option value="week">Cette semaine</option><option value="month">Ce mois</option><option value="custom">Période personnalisée</option></select><div class="datewrap"><input type="date" id="start"><button class="cal" type="button" onclick="pick('start')">📅</button></div><div class="datewrap"><input type="date" id="end"><button class="cal" type="button" onclick="pick('end')">📅</button></div><button onclick="load()">Afficher</button></div><div id="dates" class="muted"></div><div class="cards"><div class="card"><div class="lab">Commandes</div><div class="v" id="orders">—</div></div><div class="card"><div class="lab">Total commandes</div><div class="v" id="gross">—</div></div><div class="card"><div class="lab">Panier moyen</div><div class="v" id="avg">—</div></div><div class="card"><div class="lab">Remboursements</div><div class="v" id="refunds">—</div></div><div class="card"><div class="lab">Net encaissé</div><div class="v" id="net">—</div></div></div><div class="charts"><div class="box chartbox"><h2>Répartition des canaux</h2><canvas id="pieSources"></canvas><div id="legendSources" class="legend"></div></div><div class="box chartbox"><h2>Répartition des paiements</h2><canvas id="pieMethods"></canvas><div id="legendMethods" class="legend"></div></div><div class="box chartbox full"><h2>Évolution du chiffre d'affaires</h2><canvas id="lineChart"></canvas></div></div><div class="grid"><div class="box"><h2>Plats les plus vendus</h2><div id="topProducts"></div></div><div class="box"><h2>Plats les moins vendus</h2><div id="leastProducts"></div></div><div class="box"><h2>Canaux / modes</h2><div id="sources"></div></div><div class="box"><h2>Moyens de paiement</h2><div id="methods"></div></div></div><div class="warn">Lecture seule : aucun bouton de clôture et aucun Z sur cette page.</div></div><script>
const $=x=>document.getElementById(x),euro=n=>Number(n||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR'}),colors=['#143D53','#2E90FA','#12B76A','#F79009','#7F56D9','#D92D20','#06AED4','#475467','#FDB022','#0E9384'];
function pick(id){const e=$(id);if(e.showPicker)e.showPicker();else e.focus()}
$('period').onchange=()=>{let c=$('period').value==='custom';$('start').disabled=!c;$('end').disabled=!c};$('period').onchange();
function pie(id,legend,items,labelKey,valueKey){const c=$(id),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth||400,h=c.clientHeight||220;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let vals=items.map(x=>Math.max(0,Number(x[valueKey]||0))),tot=vals.reduce((a,b)=>a+b,0),a=-Math.PI/2,cx=w/2,cy=h/2,r=Math.min(w,h)*.36;if(!tot){ctx.fillStyle='#e5e7eb';ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();$(legend).innerHTML='<span class="muted">Aucune donnée</span>';return}items.forEach((x,i)=>{let na=a+Math.PI*2*(vals[i]/tot);ctx.fillStyle=colors[i%colors.length];ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,a,na);ctx.closePath();ctx.fill();a=na});ctx.fillStyle='white';ctx.beginPath();ctx.arc(cx,cy,r*.48,0,Math.PI*2);ctx.fill();$(legend).innerHTML=items.map((x,i)=>`<span><i class="dot" style="background:${colors[i%colors.length]}"></i>${x[labelKey]}</span>`).join('')}
function line(items){const c=$('lineChart'),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth||900,h=c.clientHeight||220;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let pad=38,max=Math.max(1,...items.map(x=>Number(x.total||0))),step=(w-pad*2)/Math.max(1,items.length-1);ctx.strokeStyle='#d0d5dd';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,10);ctx.lineTo(pad,h-pad);ctx.lineTo(w-10,h-pad);ctx.stroke();if(!items.length)return;ctx.strokeStyle='#143D53';ctx.lineWidth=3;ctx.beginPath();items.forEach((x,i)=>{let px=pad+i*step,py=h-pad-(Number(x.total||0)/max)*(h-pad-25);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.stroke();ctx.fillStyle='#143D53';items.forEach((x,i)=>{let px=pad+i*step,py=h-pad-(Number(x.total||0)/max)*(h-pad-25);ctx.beginPath();ctx.arc(px,py,4,0,Math.PI*2);ctx.fill()});ctx.fillStyle='#667085';ctx.font='11px Arial';items.forEach((x,i)=>{if(items.length<=12||i%Math.ceil(items.length/10)===0)ctx.fillText(x.day.slice(5),pad+i*step-12,h-12)})}
const prodRows=a=>a.length?a.map((x,i)=>`<div class="row"><span><b>${i+1}. ${x.name}</b><br><span class="muted">${x.qty} vendu${x.qty>1?'s':''}</span></span><b>${euro(x.revenue)}</b></div>`).join(''):'<div class="muted">Aucune vente</div>';
async function load(){let p=$('period').value,u='/api/statistics/today-phase44?period='+p;if(p==='custom')u+='&start='+$('start').value+'&end='+$('end').value;try{let r=await fetch(u,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Erreur');$('dates').textContent=d.start_date===d.end_date?d.start_date:d.start_date+' → '+d.end_date;$('orders').textContent=d.orders.count;$('gross').textContent=euro(d.orders.gross_total);$('avg').textContent=euro(d.orders.average_ticket);$('refunds').textContent=euro(d.cashflow.refunds);$('net').textContent=euro(d.cashflow.net);$('sources').innerHTML=d.sources.length?d.sources.map(x=>`<div class="row"><span>${x.source} (${x.count})</span><b>${euro(x.total)}</b></div>`).join(''):'<div class="muted">Aucune commande</div>';$('methods').innerHTML=d.methods.length?d.methods.map(x=>`<div class="row"><span>${x.method}</span><b>${euro(x.net)}</b></div>`).join(''):'<div class="muted">Aucun encaissement</div>';$('topProducts').innerHTML=prodRows(d.top_products||[]);$('leastProducts').innerHTML=prodRows(d.least_products||[]);pie('pieSources','legendSources',d.sources||[],'source','total');pie('pieMethods','legendMethods',d.methods||[],'method','net');line(d.daily||[])}catch(e){$('dates').textContent='Erreur : '+e.message}}load();
</script></body></html>''',content_type='text/html; charset=utf-8')